function all(promises) {
  return new Promise((resolve, reject) => {
    const out = []; let left = promises.length;
    if (left === 0) return resolve(out);
    promises.forEach((p, i) =>
      Promise.resolve(p).then((v) => {
        out[i] = v;
        if (--left === 0) resolve(out);
      }, reject));
  });
}

